    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing behavior is verified by submitting documents with low confidence scores and observing that they are directed to the human review queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under load is verified by executing the service with 50 requests per second and measuring the response times to check the 95th percentile."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The logging requirement is verified by inspecting the recorded logs or database entries to ensure the model version, input hash, and predicted category are present."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting deviation via Population Stability Index requires statistical analysis of the weekly distribution against a baseline."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The functionality is verified by submitting a document and observing that the response includes the three specified text passages."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall metrics between different language subsets requires statistical analysis of the model's performance on those specific groups."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that the specified fields are accepted and stored."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The distinct display of the four triage categories with specific colours is best verified by running the application and visually observing the UI elements."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to record valid vital signs and reject out-of-range values is verified by providing specific input data and observing the system's response."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The offline functionality and local storage capacity are verified by disconnecting the network and creating 500 records to ensure the application remains functional and stores the data."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The synchronization and conflict resolution logic is verified by simulating conflicting edits, restoring connectivity, and observing that both versions are retained for review."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The use of AES-256 encryption is verified by inspecting the code or configuration to confirm the correct cryptographic algorithm and key management are implemented."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The operability with surgical gloves is verified by a user wearing gloves interacting with the tablet interface to demonstrate that all functions are accessible."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Test"
      ],
      "rationale": "The battery life requirement is verified by running the application under the defined usage profile and measuring the duration until the battery is depleted."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresinin doğrulanması için sisteme girdi verilerek harita üzerindeki görsel çıktı ve zamanlama gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi yapılarak 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı ölçülmelidir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Test"
      ],
      "rationale": "Operatörün iz seçimi işlemi gerçekleştirilerek ekranda doğru bilgilerin görüntülenip görüntülenmediği kontrol edilmelidir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Güncelleme akışının durdurulmasıyla 30 ve 120 saniye sonrası iz durumundaki değişimlerin gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği sistemin çalıştırılmasıyla doğrulanmalıdır."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderim işlemi yapılarak iletim süresinin 2 saniyeyi aşmadığı ve durum bildiriminin gösterildiği gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test"
      ],
      "rationale": "Operatör işlemleri gerçekleştirilerek log kayıtlarının zaman damgası ve kullanıcı kimliği ile doğru ve değiştirilemez şekilde oluştuğu kontrol edilmelidir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucunun durdurulması senaryosu uygulayarak yedek sunucunun devralma süresi ve veri bütünlüğü test edilmelidir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz veya eksik OAuth 2.0 belirteci ile yapılan isteklerin HTTP 401 yanıtı döndürmesi, sistemin çalıştırılarak ve girdi verilerek gözlenebilir."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı rollerdeki istemcilerin yetkisiz uç noktalara erişim denemelerinin HTTP 403 yanıtı ile reddedilmesi, davranışsal testlerle doğrulanabilir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Dakikada 600 istekten fazla istek gönderildiğinde HTTP 429 yanıtı ve Retry-After başlığının varlığı, sistemin çalıştırılarak gözlenebilir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "2.000 istek/saniye yük altında 99. persentil gecikmenin 20 ms'yi aşmaması, performans testleri ve istatistiksel analiz gerektirir."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç servisin 5 saniyeden uzun süre yanıt vermemesi durumunda isteğin sonlandırılması ve HTTP 504 yanıtının dönmesi, simüle edilerek test edilebilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma olmadan ve devam eden istekleri düşürmeden uygulanması, sistemin çalıştırılarak gözlenebilir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "Her istek için gerekli alanların (izleme kimliği, istemci kimliği vb.) günlük dosyasına doğru şekilde yazılması, istek gönderilip günlük içeriği kontrol edilerek doğrulanabilir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık %99,95 kullanılabilirlik hedefinin sağlanması, uzun vadeli izleme verilerinin istatistiksel analizi gerektirir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı girişi yapılarak ve sonuç gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık bekleme süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışı, zamanlayıcı testleri ile sistemin çalıştırılarak gözlemlenebilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık süre, sisteme girdi verilerek ve kilit durumu gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kurallarının uygulanıp uygulanmadığı, farklı senaryolarla sisteme dosya yüklenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanınca benzersiz numara üretimi ve e-posta gönderimi, işlem gerçekleştirilip çıktıların (numara ve e-posta) kontrol edilmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde devam etme işlevi, formu yarım bırakıp farklı zamanlarda sisteme giriş yapılarak gözlemlenebilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, kullanıcı arayüzünün kod yapısı, HTML semantiği ve erişilebilirlik araçlarıyla üretilen raporların gözle denetlenmesiyle doğrulanır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma dosyaları, sunucu konum bilgileri ve sözleşmelerin gözle incelenmesiyle doğrulanır."
    }
  ]
}

