{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Macro-averaged F1 score verification on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. A held-out evaluation set is available and accessible.",
      "test_inputs": "Held-out evaluation dataset containing labeled documents.",
      "assumptions": "The evaluation script correctly calculates the macro-averaged F1 score.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation process on the held-out evaluation set using the trained model.",
          "expected": "The system completes the evaluation without errors."
        },
        {
          "no": 2,
          "action": "Retrieve the calculated macro-averaged F1 score from the evaluation results.",
          "expected": "The macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Recall difference between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. A held-out evaluation set containing both Turkish and English documents is available.",
      "test_inputs": "Held-out evaluation dataset with labeled Turkish and English documents.",
      "assumptions": "The evaluation script correctly calculates recall for each language subset.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation process on the held-out evaluation set, filtering results by document language (Turkish and English).",
          "expected": "The system completes the evaluation and provides recall metrics for both Turkish and English subsets."
        },
        {
          "no": 2,
          "action": "Calculate the absolute difference between the recall score for Turkish documents and the recall score for English documents.",
          "expected": "The difference is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Kullanıcı arayüzünün WCAG 2.1 AA uyumluluğunun doğrulanması",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Sistem yayınlamış ve erişilebilirlik test araçları (ör. Lighthouse, axe-core) hazır durumdadır.",
      "test_inputs": "Portalın ana sayfası ve temel başvuru formu URL'leri.",
      "assumptions": "Erişilebilirlik testleri, standart tarayıcı eklentileri veya otomatik tarama araçları ile gerçekleştirilecektir.",
      "steps": [
        {
          "no": 1,
          "action": "Portalın ana sayfası ve temel başvuru formu sayfaları, WCAG 2.1 AA uyumluluğu için otomatik tarama araçları ile analiz edilir.",
          "expected": "Tarama sonuçlarında WCAG 2.1 AA düzeyinde hata (error) bulunmaz; yalnızca uyarılar (warning) veya bilgi (info) seviyesinde bulgular olabilir."
        },
        {
          "no": 2,
          "action": "Sayfalar klavye navigasyonu ile taranır ve tüm etkileşimli öğelere (butonlar, giriş alanları, menüler) klavye ile erişilebilirliği kontrol edilir.",
          "expected": "Tüm etkileşimli öğeler klavye ile sırayla gezilebilir, odak (focus) durumu görsel olarak belirgindir ve klavye kısayolları çakışma olmadan çalışır."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and running on the tablet. A test casualty record has been created and saved.",
      "test_inputs": "A sample casualty record with unique identifiers (e.g., Name: 'Test Patient', ID: '12345').",
      "assumptions": "Access to the device's file system or storage dump is available for inspection.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record in the application and save it.",
          "expected": "The record is successfully saved and visible in the application interface."
        },
        {
          "no": 2,
          "action": "Access the underlying storage file or database where the casualty data is persisted.",
          "expected": "The raw data is not readable as plain text; it appears as encrypted binary data."
        },
        {
          "no": 3,
          "action": "Verify the encryption algorithm used for the stored data using a forensic tool or configuration check.",
          "expected": "The encryption method is confirmed to be AES-256."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Battery life under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100%). The 'defined usage profile' is documented and available (e.g., continuous triage input, screen on, Wi-Fi on).",
      "test_inputs": "None (continuous operation).",
      "assumptions": "The 'defined usage profile' involves continuous application usage with screen brightness at 50% and Wi-Fi enabled. A timer is used to track duration.",
      "steps": [
        {
          "no": 1,
          "action": "Start the application and begin the defined usage profile (e.g., entering triage data continuously).",
          "expected": "The application operates normally, and the battery level starts at 100%."
        },
        {
          "no": 2,
          "action": "Continue the defined usage profile until the battery is depleted or the device shuts down.",
          "expected": "The device remains operational for at least 8 hours before shutting down or requiring a charge."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Offline functionality and local storage capacity",
      "covers": [
        "MED-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and configured. Network connectivity is disabled (airplane mode or no signal). The local database is empty.",
      "test_inputs": "500 unique casualty record data sets.",
      "assumptions": "The application allows manual creation of casualty records. 'Fully functional' implies the ability to create, read, and update records locally.",
      "steps": [
        {
          "no": 1,
          "action": "Create 500 distinct casualty records in the application while offline.",
          "expected": "All 500 records are successfully saved to the local storage without errors or data loss."
        },
        {
          "no": 2,
          "action": "Attempt to view, edit, and delete a sample of the created records while offline.",
          "expected": "The application responds correctly to all operations, displaying accurate data and reflecting changes immediately in the local view."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Synchronization upon connectivity restoration",
      "covers": [
        "MED-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is offline. 10 local casualty records have been created. Network connectivity is available but the app is not connected to the server.",
      "test_inputs": "10 local casualty records.",
      "assumptions": "The server is running and accessible. The local records do not conflict with existing server records (unique IDs or new entries).",
      "steps": [
        {
          "no": 1,
          "action": "Enable network connectivity and trigger or wait for the synchronization process to start.",
          "expected": "The application initiates synchronization with the server."
        },
        {
          "no": 2,
          "action": "Wait for the synchronization process to complete.",
          "expected": "The 10 local records are successfully transmitted to the server. The local status of these records is updated to 'synced' or similar."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Conflict resolution by keeping both versions",
      "covers": [
        "MED-005"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A casualty record (ID: C-123) exists on the server with status 'Stable'. The same record (ID: C-123) is modified locally while offline to status 'Critical'. Network connectivity is restored.",
      "test_inputs": "Local edit: Status changed to 'Critical'. Server state: Status 'Stable'.",
      "assumptions": "The application detects the conflict based on version numbers or timestamps. 'Manual review' implies a specific UI state or list for conflicts.",
      "steps": [
        {
          "no": 1,
          "action": "Enable network connectivity to trigger synchronization.",
          "expected": "The application detects a conflict for record C-123."
        },
        {
          "no": 2,
          "action": "Check the status of record C-123 in the application.",
          "expected": "The record is not automatically overwritten. Both the local version ('Critical') and the server version ('Stable') are preserved and flagged for manual review."
        },
        {
          "no": 3,
          "action": "Navigate to the conflict review section or view the record details.",
          "expected": "The user can see both versions of the data and is provided with an option to resolve the conflict manually."
        }
      ]
    }
  ]
}

