{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Configuration change applied without restart",
      "covers": [
        "SW-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Gateway is running and active.",
      "test_inputs": "A valid configuration change (e.g., updating a rate limit value).",
      "assumptions": "The configuration management interface allows dynamic updates.",
      "steps": [
        {
          "no": 1,
          "action": "Apply a configuration change to the running gateway.",
          "expected": "The configuration change is accepted and the gateway does not restart."
        },
        {
